import sys, struct, re
sys.path.insert(0, '/tmp/kit')
from elfkit import *

PT_NOTE = 4
SHT_NOTE = 7

def note(name, desc, ntype, namesz=None, descsz=None, nalign=4, dalign=4, nul=True):
    """Build a raw note record. name is bytes (NUL appended if nul)."""
    nb = name + (b'\x00' if nul else b'')
    if namesz is None:
        namesz = len(nb)
    if descsz is None:
        descsz = len(desc)
    out = struct.pack('<III', namesz, descsz, ntype)
    out += nb
    if nalign:
        while len(out) % nalign:
            out += b'\x00'
    out += desc
    if dalign:
        while len(out) % dalign:
            out += b'\x00'
    return out

def notes_seg(blob, off=0x200, ptype=PT_NOTE, align=0, filesize=None, extra_phdrs=(), **kw):
    phdrs = [dict(ptype=ptype, off=off, filesz=len(blob), memsz=len(blob), align=align)]
    phdrs += list(extra_phdrs)
    fs = filesize if filesize else off + len(blob) + 0x10
    return build(phdrs=phdrs, filesize=fs, patch=[(off, blob)], **kw)

def nrows(h, tid='info_segment0'):
    t = itable(h, tid)
    if t is None:
        return None
    return t

def dump(h, tid='info_segment0'):
    t = nrows(h, tid)
    print('---', tid, '---')
    print(t)

def subranges(h):
    rs, total = span_ranges(h)
    return [(s, e, c) for s, e, d, c in rs if 'subrange' in c]

